import{Ct as e,at as t,it as n,ot as r,st as i,t as a,yt as o}from"./chunks/framework.C2psWpP8.js";var s=JSON.parse('{"title":"@warp-drive/legacy/compat","description":"Legacy store support for adapters and serializers: the `LegacyNetworkHandler` plus store methods such as `adapterFor`, `serializerFor`, `normalize` and `pushPayload`.","frontmatter":{"title":"@warp-drive/legacy/compat","description":"Legacy store support for adapters and serializers: the `LegacyNetworkHandler` plus store methods such as `adapterFor`, `serializerFor`, `normalize` and `pushPayload`.","outline":{"level":[2,3]}},"headers":[],"relativePath":"api/@warp-drive/legacy/compat/index.md","filePath":"api/@warp-drive/legacy/compat/index.md"}'),c={name:`api/@warp-drive/legacy/compat/index.md`};function l(a,s,c,l,u,d){let f=e(`ModuleBadge`),p=e(`Badge`);return o(),n(`div`,null,[i(f,{path:`@warp-drive/legacy/compat`}),s[0]||=r(),i(p,{type:`danger`,text:`@legacy`}),s[1]||=t(`<p>Helps an app migrate incrementally from legacy EmberData patterns to modern <strong><em>Warp</em>Drive</strong>.</p><h2 id="why-it-exists" tabindex="-1">Why it exists <a class="header-anchor" href="#why-it-exists" aria-label="Permalink to “Why it exists”">​</a></h2><p>While migrating, you may need to:</p><ul><li>keep Adapters and Serializers working on a Store whose requests go through the <a href="./../../core/classes/RequestManager">RequestManager</a></li><li>keep the deprecated request methods such as <code>store.findRecord</code> and <code>store.query</code>, which Adapters fulfill, working while you move calls to <code>store.request</code></li><li>adopt modern patterns one piece at a time rather than all at once</li></ul><h2 id="what-it-provides" tabindex="-1">What it provides <a class="header-anchor" href="#what-it-provides" aria-label="Permalink to “What it provides”">​</a></h2><ul><li><a href="./variables/LegacyNetworkHandler">LegacyNetworkHandler</a>, a request handler that fulfills those legacy requests through the store&#39;s Adapters and Serializers and passes every other request along</li><li><a href="./functions/adapterFor">adapterFor</a>, <a href="./functions/serializerFor">serializerFor</a>, <a href="./functions/normalize">normalize</a>, <a href="./functions/pushPayload">pushPayload</a> and <a href="./functions/serializeRecord">serializeRecord</a>, the store methods for working with Adapters and Serializers, and <a href="./types/LegacyStoreCompat">LegacyStoreCompat</a>, the Store type that includes them</li></ul><p>The Store that <a href="/pr-preview/pr-11237/api/@warp-drive/legacy/functions/useLegacyStore">useLegacyStore</a> produces adds <code>LegacyNetworkHandler</code> to its RequestManager unless <code>linksMode</code> is <code>true</code>. The hooks that present <code>Model</code> instances live in <a href="/pr-preview/pr-11237/api/@warp-drive/legacy/model/">@warp-drive/legacy/model</a>, not here.</p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to “When to use it”">​</a></h2><p>Only during a migration from legacy EmberData to modern <strong><em>Warp</em>Drive</strong>. It lets you adopt modern patterns incrementally while your existing Adapters and Serializers keep working. For incremental migration strategies, see the <a href="/pr-preview/pr-11237/upgrading/v5/">Migration Guide</a> and the <a href="/pr-preview/pr-11237/upgrading/v5/two-store-migration">Two Store Migration Strategy</a>.</p><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to “Variables”">​</a></h2><ul><li><a href="./variables/LegacyNetworkHandler">LegacyNetworkHandler</a></li></ul><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to “Functions”">​</a></h2><ul><li><a href="./functions/adapterFor">adapterFor</a></li><li><a href="./functions/cleanup">cleanup</a></li><li><a href="./functions/normalize">normalize</a></li><li><a href="./functions/pushPayload">pushPayload</a></li><li><a href="./functions/serializeRecord">serializeRecord</a></li><li><a href="./functions/serializerFor">serializerFor</a></li></ul><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to “Types”">​</a></h2><ul><li><a href="./types/LegacyStoreCompat">LegacyStoreCompat</a></li><li><a href="./types/MinimumAdapterInterface">MinimumAdapterInterface</a></li><li><a href="./types/MinimumSerializerInterface">MinimumSerializerInterface</a></li><li><a href="./types/AdapterPayload">AdapterPayload</a></li><li><a href="./types/CompatStore"><s>CompatStore</s></a></li><li><a href="./types/SerializerOptions">SerializerOptions</a></li></ul>`,15)])}var u=a(c,[[`render`,l]]);export{s as __pageData,u as default};